// @ts-nocheck — Orval's generated UseQueryOptions requires queryKey even though its builder supplies one.
import { useState, type ReactNode } from 'react';
import { Link, useLocation, useParams } from 'wouter';
import { useQueryClient } from '@tanstack/react-query';
import { useClerk, useUser } from '@clerk/react';
import { Activity, ArrowLeft, ArrowRight, Bell, Building2, Check, ChevronLeft, ChevronRight, ClipboardList, Clock3, Command, ExternalLink, FileClock, Fingerprint, ListChecks, LogOut, Menu, RefreshCw, Search, ShieldCheck, ShieldAlert, Sparkles, Users, X } from 'lucide-react';
import {
  useGetMissionControlMe, useGetMissionControlOverview, useListMissionControlCompanies, useGetMissionControlCompany, useUpdateMissionControlCompanyAccess,
  useListMissionControlTechnicians, useGetMissionControlTechnician, useUpdateMissionControlUserAccess, useListMissionControlInspections, useGetMissionControlInspection,
  useListMissionControlIncidents, useGetMissionControlIncident, useUpdateMissionControlIncident, useListMissionControlAudit,
  useListMissionControlAgents, useListMissionControlAgentTasks, useCreateMissionControlAgentTask, useGetMissionControlAgentTask,
  useListMissionControlApprovals, useDecideMissionControlApproval,
  getGetMissionControlCompanyQueryKey, getGetMissionControlInspectionQueryKey, getGetMissionControlIncidentQueryKey, getGetMissionControlAgentTaskQueryKey, getGetMissionControlTechnicianQueryKey
} from '@workspace/api-client-react';

const nav = [
  {href:'/',label:'Overview',icon:Activity},{href:'/companies',label:'Companies',icon:Building2},{href:'/technicians',label:'Technicians',icon:Users},
  {href:'/inspections',label:'Inspections',icon:ClipboardList},{href:'/incidents',label:'Incidents',icon:ShieldAlert},{href:'/audit',label:'Audit trail',icon:FileClock},
  {href:'/agents',label:'Agents & tasks',icon:Command},{href:'/approvals',label:'Approvals',icon:ListChecks}
];
const date = (v?:string|null) => v ? new Date(v).toLocaleString(undefined,{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}) : 'Not recorded';
const tone = (v?:string|null) => !v ? 'neutral' : /critical|high|failed|suspended|rejected|open|error/.test(v.toLowerCase()) ? 'bad' : /pending|queued|medium|investigating|running/.test(v.toLowerCase()) ? 'warn' : /unknown|unavailable/.test(v.toLowerCase()) ? 'neutral' : '';
function Badge({value}:{value?:string|null}) {return <span className={`status ${tone(value)}`} data-testid={`status-${value || 'unknown'}`}><span className="dot"/>{value || 'Unknown'}</span>}
function Header({kicker,title,description,action}:{kicker:string,title:string,description?:string,action?:ReactNode}) {return <div className="flex flex-col sm:flex-row sm:items-end sm:justify-between gap-5 mb-7"><div><div className="eyebrow mb-3">{kicker}</div><h1 className="display text-[36px] sm:text-[46px] leading-[1.05] font-bold" data-testid="text-page-title">{title}</h1>{description && <p className="text-[#677a7b] mt-3 max-w-2xl">{description}</p>}</div>{action}</div>}
function State({loading,error,empty,children,onRetry,emptyText='Nothing to show yet.'}:{loading:boolean,error:boolean,empty?:boolean,children:ReactNode,onRetry?:()=>void,emptyText?:string}) {
  if(loading) return <div className="surface p-6 space-y-5" data-testid="status-loading"><div className="skeleton h-6 w-1/3"/>{[1,2,3,4].map(i=><div key={i} className="skeleton h-14 w-full"/>)}</div>;
  if(error) return <div className="surface p-9 text-center" data-testid="status-error"><ShieldAlert className="mx-auto text-[#a8433e] mb-3"/><h2 className="display text-xl font-bold">We couldn’t load this view.</h2><p className="text-[#6b7c7d] mt-2 mb-5">The data is unchanged. Try again when the connection is ready.</p><button className="btn btn-dark" onClick={onRetry} data-testid="button-retry">Try again</button></div>;
  if(empty) return <div className="surface p-12 text-center" data-testid="status-empty"><div className="w-12 h-12 rounded-xl bg-[#e7f0e9] flex items-center justify-center mx-auto mb-4"><ListChecks size={22} className="text-[#126b63]"/></div><h2 className="display text-xl font-bold">All clear here</h2><p className="text-[#6b7c7d] mt-2">{emptyText}</p></div>;
  return <>{children}</>;
}
function Pager({page,totalPages,onPage}:{page:number,totalPages:number,onPage:(n:number)=>void}) {return <div className="flex justify-between items-center mt-5 text-sm text-[#617476]"><span className="mono text-[11px]">PAGE {page} / {Math.max(totalPages,1)}</span><div className="flex gap-2"><button className="btn btn-light" disabled={page<=1} onClick={()=>onPage(page-1)} data-testid="button-prev-page"><ChevronLeft size={17}/> Previous</button><button className="btn btn-light" disabled={page>=totalPages} onClick={()=>onPage(page+1)} data-testid="button-next-page">Next <ChevronRight size={17}/></button></div></div>}
function SearchField({value,onChange,placeholder}:{value:string,onChange:(v:string)=>void,placeholder:string}) {return <div className="relative"><Search size={17} className="absolute left-3 top-3 text-[#7a8987]"/><input className="field pl-10" type="search" value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} data-testid="input-search"/></div>}
function Back({to,label}:{to:string,label:string}) {return <Link href={to} className="inline-flex items-center gap-2 text-[#126b63] font-bold mb-6 hover:underline" data-testid="link-back"><ArrowLeft size={16}/>{label}</Link>}
function DetailGrid({fields}:{fields:[string,ReactNode][]}) {return <div className="surface grid sm:grid-cols-2 lg:grid-cols-3">{fields.map(([key,val])=><div className="p-5 border-b border-r border-[#e5e9e3]" key={key}><div className="label">{key}</div><div className="font-semibold break-words" data-testid={`text-${key.toLowerCase().replace(/\s/g,'-')}`}>{val ?? 'Not recorded'}</div></div>)}</div>}

export function PublicLanding() {return <div className="min-h-[100dvh] bg-[#e9eee8]"><header className="px-6 md:px-12 py-6 flex justify-between items-center border-b border-[#cbd7d1]"><Brand dark/><Link href="/sign-in" className="btn btn-dark" data-testid="link-sign-in">Operator sign in <ArrowRight size={16}/></Link></header><main className="max-w-7xl mx-auto px-6 md:px-12"><section className="min-h-[650px] flex flex-col justify-center py-20 relative overflow-hidden"><div className="eyebrow mb-7">READYLOQ / PLATFORM OPERATIONS</div><h1 className="display font-bold text-[clamp(4rem,10vw,9.5rem)] leading-[.88] max-w-[1050px]">Stay ahead<br/>of the <em className="not-italic text-[#0c7065]">signal.</em></h1><div className="mt-11 flex flex-col md:flex-row md:items-end gap-9 max-w-3xl"><p className="text-xl text-[#4e676a] leading-relaxed max-w-xl">A private command center for the people responsible for ReadyLoq. See platform health, investigate inspections, and make consequential decisions with a clear record.</p><Link href="/sign-in" className="btn btn-primary whitespace-nowrap self-start" data-testid="link-enter-console">Enter mission control <ArrowRight size={17}/></Link></div><div className="absolute right-0 bottom-10 hidden lg:block mono text-[10px] tracking-widest text-[#7c928f] rotate-90 origin-right">CONTROL / CLARITY / ACCOUNTABILITY</div></section><section className="grid lg:grid-cols-[1fr_2fr] gap-10 py-16 border-t border-[#cbd7d1]"><div><div className="eyebrow">01 / A dedicated surface</div><h2 className="display text-4xl font-bold mt-5">Operations, not another portal.</h2></div><div className="grid sm:grid-cols-2 gap-4">{[['Cross-company visibility','Survey companies, technicians, inspections, and incidents without changing tenant context.'],['Traceable decisions','Review approvals, assign ownership, and keep an audit trail for high-stakes actions.'],['Inspection diagnostics','Trace media, analysis, and sync activity from a single inspection record.'],['Human oversight','See the real agent roster and persisted tasks. Nothing here pretends work happened.']].map(([a,b],i)=><div className="surface panel" key={a}><span className="mono text-[#127166] text-xs">0{i+1}</span><h3 className="display font-bold text-xl mt-6">{a}</h3><p className="text-[#677b7b] mt-2 leading-relaxed">{b}</p></div>)}</div></section><section className="bg-[#20343a] text-[#f4f1e8] rounded-[24px] p-8 md:p-14 my-16 flex flex-col md:flex-row gap-8 justify-between items-end"><div><Fingerprint className="text-[#e8ba69] mb-8" size={32}/><div className="eyebrow !text-[#e8ba69]">Restricted access</div><h2 className="display text-4xl md:text-6xl font-bold mt-4 max-w-2xl">Built for trusted hands only.</h2><p className="text-[#b6c8c6] mt-5 max-w-lg">Sign-in establishes identity. Platform access requires separate super-admin authorization. Creating an account never grants operational access.</p></div><Link href="/sign-in" className="btn bg-[#e8ba69] text-[#20343a] shrink-0" data-testid="link-secure-sign-in">Secure sign in <ArrowRight size={17}/></Link></section></main><footer className="px-6 md:px-12 py-8 border-t border-[#cbd7d1] flex justify-between text-xs text-[#647977]"><span>READYLOQ / MISSION CONTROL</span><span>Internal operations environment</span></footer></div>}
function Brand({dark=false}:{dark?:boolean}) {return <div className={`flex items-center gap-3 ${dark?'text-[#20343a]':'text-[#f0f2e8]'}`}><span className={`w-9 h-9 rounded-[10px] grid place-items-center ${dark?'bg-[#20343a] text-[#eac479]':'bg-[#e8ba69] text-[#20343a]'}`}><Command size={20} strokeWidth={2.5}/></span><span className="display text-xl font-extrabold tracking-tight">readyloq<span className="text-[#0e7b6d]">.</span></span></div>}
export function AccessDenied(){const {signOut}=useClerk();return <div className="min-h-[100dvh] bg-[#e9eee8] grid place-items-center p-6"><div className="surface max-w-lg p-9"><div className="eyebrow">ACCESS CONTROL / 403</div><ShieldAlert className="mt-8 text-[#a8433e]" size={38}/><h1 className="display text-4xl font-bold mt-6">This console is restricted.</h1><p className="text-[#627577] mt-4 leading-relaxed">Your sign-in succeeded, but this account is not authorized as a ReadyLoq platform super-admin. No operational data has been loaded.</p><button className="btn btn-dark mt-7" onClick={()=>signOut({redirectUrl:import.meta.env.BASE_URL})} data-testid="button-sign-out">Sign out</button></div></div>}
export function Gate({children}:{children:ReactNode}) {const q=useGetMissionControlMe({query:{retry:false,refetchOnWindowFocus:true}});if(q.isLoading)return <div className="min-h-[100dvh] bg-[#e9eee8] grid place-items-center p-6"><div className="skeleton h-40 w-full max-w-md"/></div>;if(q.isError)return <div className="min-h-[100dvh] bg-[#e9eee8] grid place-items-center p-6"><State loading={false} error onRetry={()=>q.refetch()}>{null}</State></div>;if(!q.data?.isSuperAdmin)return <AccessDenied/>;return <>{children}</>}
export function Shell({children}:{children:ReactNode}) {const [path]=useLocation();const [mobile,setMobile]=useState(false);const [company,setCompany]=useState('');const [scope,setScope]=useState(0);const {signOut}=useClerk();const {user}=useUser();const companies=useListMissionControlCompanies({page:scope+1,limit:100},{query:{staleTime:60000}});const title=nav.find(x=>x.href===path || (x.href!=='/'&&path.startsWith(x.href+'/')))?.label||'Mission control';return <ScopeContext.Provider value={{companyId:company?Number(company):undefined}}><div className="min-h-[100dvh] md:flex bg-[#f3f4ed]"><aside className={`${mobile?'flex':'hidden'} md:flex fixed md:sticky z-30 inset-y-0 left-0 w-[276px] md:h-[100dvh] bg-[#20343a] text-[#e9eee4] flex-col shrink-0`}><div className="p-7 border-b border-[#3b5053] flex items-center justify-between"><Brand/><button onClick={()=>setMobile(false)} className="md:hidden" aria-label="Close menu" data-testid="button-close-menu"><X/></button></div><div className="p-6 pt-8"><div className="mono text-[10px] text-[#a7bcb9] tracking-[.2em]">PLATFORM / ADMIN</div><div className="flex items-center gap-2 mt-3 text-xs text-[#d7e3db]"><span className="w-2 h-2 rounded-full bg-[#eac479]"/> Secure operations</div></div><nav className="px-3 flex-1 overflow-auto" aria-label="Main navigation">{nav.map(item=><Link key={item.href} href={item.href} onClick={()=>setMobile(false)} data-testid={`link-${item.label.toLowerCase().replace(/[^a-z]+/g,'-')}`} className={`flex items-center gap-3 px-4 py-3 rounded-lg mb-1 text-[13px] font-semibold transition-colors ${path===item.href||(item.href!=='/'&&path.startsWith(item.href+'/'))?'bg-[#e6bc71] text-[#20343a]':'text-[#b5c7c5] hover:bg-[#32484b] hover:text-[#f5f2e9]'}`}><item.icon size={17}/>{item.label}</Link>)}</nav><div className="p-5 border-t border-[#3b5053]"><div className="text-sm font-semibold truncate">{user?.fullName||user?.primaryEmailAddress?.emailAddress||'Operator'}</div><div className="mono text-[10px] text-[#a8bdbb] mt-1">SUPER ADMIN SESSION</div><button className="flex items-center gap-2 text-xs text-[#b5c7c5] mt-5 hover:text-white" onClick={()=>signOut({redirectUrl:import.meta.env.BASE_URL})} data-testid="button-sign-out"><LogOut size={15}/> Sign out</button></div></aside>{mobile&&<button className="fixed inset-0 z-20 bg-[#142c30]/60 md:hidden" aria-label="Close navigation" onClick={()=>setMobile(false)} data-testid="button-menu-overlay"/>}<div className="flex-1 min-w-0"><header className="h-[76px] bg-[#f9f9f3] border-b border-[#dbe3dc] px-5 md:px-10 flex items-center justify-between gap-4"><div className="flex items-center gap-4"><button className="md:hidden p-2" onClick={()=>setMobile(true)} aria-label="Open menu" data-testid="button-open-menu"><Menu/></button><span className="text-xs font-bold text-[#708382] uppercase tracking-[.13em] hidden sm:block">Workspace</span><span className="hidden sm:block text-[#c6d3ce]">/</span><span className="font-semibold">{title}</span></div><div className="flex items-center gap-3"><label className="hidden sm:block mono text-[10px] text-[#718381]">COMPANY SCOPE</label><select className="field !w-[160px] sm:!w-[205px] !min-h-[37px] !py-1 text-xs font-semibold" value={company} onChange={e=>setCompany(e.target.value)} data-testid="select-company-scope"><option value="">All companies</option>{companies.data?.items.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select>{(companies.data?.totalPages||0)>1&&<button className="text-[10px] text-[#126b63] font-bold" onClick={()=>setScope(s=>s+1>= (companies.data?.totalPages||1)?0:s+1)} data-testid="button-more-companies">More</button>}</div></header><main className="px-5 md:px-10 py-8 md:py-10 max-w-[1600px] mx-auto fade-in">{children}</main></div></div></ScopeContext.Provider>}
import { createContext, useContext } from 'react';
const ScopeContext=createContext<{companyId?:number}>({});
export const useScope=()=>useContext(ScopeContext);
function Refresh({run}:{run:()=>void}){return <button className="btn btn-light" onClick={run} data-testid="button-refresh"><RefreshCw size={15}/> Refresh</button>}
export function Overview(){const q=useGetMissionControlOverview({query:{refetchInterval:60000}});const k=q.data?.kpis;return <><Header kicker="PLATFORM / LIVE VIEW" title="A clear view of what matters." description="A real-time starting point for platform operations. Counts and alerts come directly from ReadyLoq." action={<Refresh run={()=>q.refetch()}/>}/><State loading={q.isLoading} error={q.isError} onRetry={()=>q.refetch()}><div className="grid lg:grid-cols-[1.4fr_1fr] gap-5"><div className="surface overflow-hidden"><div className="p-6 md:p-8 bg-[#20343a] text-[#f5f1e7]"><div className="eyebrow !text-[#e8ba69]">PLATFORM PULSE</div><div className="display text-[46px] md:text-[72px] leading-none font-bold mt-6">{k?.inspectionCount?.toLocaleString()??'—'}</div><div className="text-[#b4c7c2] mt-2">inspections recorded across the platform</div></div><div className="grid grid-cols-2 md:grid-cols-3">{[['Companies',k?.companyCount],['Active companies',k?.activeCompanyCount],['Users',k?.userCount],['Technicians',k?.technicianCount],['Open incidents',k?.openIncidentCount]].map(([a,b])=><div className="p-6 border-r border-b border-[#e4e9e2]" key={a}><div className="display text-3xl font-bold" data-testid={`text-kpi-${String(a).toLowerCase().replace(' ','-')}`}>{b?.toLocaleString()??'—'}</div><div className="text-xs text-[#71817e] mt-2">{a}</div></div>)}</div></div><div className="surface"><div className="p-6 border-b border-[#e2e8e0] flex justify-between items-center"><div><div className="eyebrow">ATTENTION</div><h2 className="display text-2xl font-bold mt-2">Recent alerts</h2></div><Bell size={20} className="text-[#126b63]"/></div>{q.data?.recentAlerts.length?q.data.recentAlerts.map(a=><div key={a.id} className="p-5 border-b border-[#e2e8e0]"><div className="flex items-center gap-2"><Badge value={a.severity}/><span className="mono text-[10px] text-[#71827d]">{date(a.createdAt)}</span></div><div className="font-bold mt-3">{a.title}</div><p className="text-sm text-[#617476] mt-1">{a.message}</p>{a.companyId&&<Link href={`/companies/${a.companyId}`} className="text-xs font-bold text-[#126b63] inline-flex items-center gap-1 mt-2" data-testid={`link-alert-company-${a.id}`}>View company <ArrowRight size={13}/></Link>}</div>):<div className="p-8 text-[#71817e]">No recent alerts.</div>}</div></div><div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-3 mt-5">{nav.filter(x=>['/incidents','/inspections','/approvals','/audit'].includes(x.href)).map(x=><Link className="surface p-5 flex items-center justify-between hover:border-[#75aaa1] transition-colors" href={x.href} key={x.href} data-testid={`link-quick-${x.label}`}><span className="font-semibold flex gap-3 items-center"><x.icon size={17} className="text-[#126b63]"/>{x.label}</span><ArrowRight size={16}/></Link>)}</div></State></>}
export function Companies(){const [search,setSearch]=useState('');const [page,setPage]=useState(1);const q=useListMissionControlCompanies({page,limit:20,search:search||undefined});return <><Header kicker="DIRECTORY / TENANTS" title="Companies" description="Access, activity, and ownership across every ReadyLoq tenant." action={<Refresh run={()=>q.refetch()}/>}/><div className="max-w-md mb-5"><SearchField value={search} onChange={v=>{setSearch(v);setPage(1)}} placeholder="Search companies"/></div><State loading={q.isLoading} error={q.isError} onRetry={()=>q.refetch()} empty={!q.data?.items.length} emptyText="No companies match this search."><div className="surface overflow-hidden"><div className="px-5 py-4 text-xs text-[#6c7c7d] font-semibold">{q.data?.total} companies</div>{q.data?.items.map(c=><Link href={`/companies/${c.id}`} className="row-link" key={c.id} data-testid={`link-company-${c.id}`}><span className="w-10 h-10 rounded-lg bg-[#e2eee9] grid place-items-center text-[#126b63] font-bold">{c.name.slice(0,1)}</span><span className="flex-1 min-w-0"><span className="font-bold block truncate">{c.name}</span><span className="text-xs text-[#7b8a88]">{c.technicianCount} technicians · {c.inspectionCount} inspections · Last active {date(c.lastActivityAt)}</span></span><Badge value={c.accessStatus}/><ArrowRight size={16} className="text-[#81918f] hidden sm:block"/></Link>)}</div><Pager page={page} totalPages={q.data?.totalPages||1} onPage={setPage}/></State></>}
export function CompanyDetail(){const {id}=useParams();const n=Number(id);const q=useGetMissionControlCompany(n);const m=useUpdateMissionControlCompanyAccess();const u=useUpdateMissionControlUserAccess();const qc=useQueryClient();const [approval,setApproval]=useState('');const [reason,setReason]=useState('');const [userApproval,setUserApproval]=useState('');const [error,setError]=useState('');const c=q.data;const refresh=()=>{qc.invalidateQueries({queryKey:getGetMissionControlCompanyQueryKey(n)});qc.invalidateQueries({queryKey:['/api/mission-control/companies']});qc.invalidateQueries({queryKey:['/api/mission-control/audit']})};return <><Back to="/companies" label="All companies"/><Header kicker={`TENANT / ${id}`} title={c?.name||'Company detail'} description="Tenant access changes require an approved request ID. Changes are recorded in the audit trail." action={<Refresh run={()=>q.refetch()}/>}/><State loading={q.isLoading} error={q.isError} onRetry={()=>q.refetch()}><DetailGrid fields={[[ 'Access',<Badge value={c?.accessStatus}/>],['Owner',c?.owner?.name||'—'],['Owner email',c?.owner?.email||'—'],['Users',c?.userCount],['Technicians',c?.technicianCount],['Inspections',c?.inspectionCount],['Created',date(c?.createdAt)],['Last activity',date(c?.lastActivityAt)]]}/><div className="grid lg:grid-cols-[1fr_1.4fr] gap-5 mt-5"><div className="surface panel"><div className="eyebrow">CONTROL / TENANT ACCESS</div><h2 className="display text-2xl font-bold mt-2">Access control</h2><p className="text-[#687b7a] mt-2 mb-5">Enter the ID of an approved access request before changing tenant access.</p><label className="label" htmlFor="company-approval">Approved request ID</label><input id="company-approval" className="field" type="number" min="1" value={approval} onChange={e=>setApproval(e.target.value)} data-testid="input-company-approval"/><label className="label mt-4" htmlFor="company-reason">Reason (optional)</label><textarea id="company-reason" className="field" value={reason} onChange={e=>setReason(e.target.value)} data-testid="input-company-reason"/><button className={`btn mt-4 ${c?.accessStatus==='enabled'?'btn-danger':'btn-primary'}`} disabled={!approval||m.isPending} onClick={()=>m.mutate({id:n,data:{action:c?.accessStatus==='enabled'?'suspend':'enable',approvalId:Number(approval),reason:reason||undefined}},{onSuccess:()=>{setApproval('');setReason('');setError('');refresh()},onError:e=>setError(String(e))})} data-testid="button-company-access">{m.isPending?'Updating…':c?.accessStatus==='enabled'?'Suspend company':'Enable company'}</button>{error&&<p className="text-[#a8433e] mt-3" role="alert">{error}</p>}</div><div className="surface overflow-hidden"><div className="p-6"><div className="eyebrow">PEOPLE</div><h2 className="display text-2xl font-bold mt-2">Company users</h2><div className="mt-4"><label className="label" htmlFor="user-approval">Approved user-access request ID</label><input id="user-approval" type="number" min="1" className="field" value={userApproval} onChange={e=>setUserApproval(e.target.value)} data-testid="input-user-approval"/></div></div>{c?.users?.length?c.users.map(person=><div className="row-link" key={person.id}><div className="flex-1 min-w-0"><div className="font-bold truncate">{person.name}</div><div className="text-xs text-[#70817e] truncate">{person.email} · {person.role||'User'}</div></div><Badge value={person.betaAccessEnabled?'Beta enabled':'Beta disabled'}/><button className="btn btn-light !text-xs" disabled={!userApproval||u.isPending} onClick={()=>u.mutate({id:person.id,data:{action:person.betaAccessEnabled?'disable':'enable',approvalId:Number(userApproval)}},{onSuccess:()=>{setUserApproval('');setError('');refresh()},onError:e=>setError(String(e))})} data-testid={`button-user-access-${person.id}`}>{person.betaAccessEnabled?'Disable':'Enable'}</button></div>):<div className="p-6 text-[#71817e]">No users recorded.</div>}{u.isError&&<p className="p-5 text-[#a8433e]" role="alert">{String(u.error)}</p>}</div></div><div className="surface mt-5 overflow-hidden"><div className="p-6"><div className="eyebrow">ACTIVITY</div><h2 className="display text-2xl font-bold mt-2">Recent inspections</h2></div>{c?.recentInspections?.length?c.recentInspections.map(i=><Link className="row-link" href={`/inspections/${i.id}`} key={i.id} data-testid={`link-company-inspection-${i.id}`}><span className="mono text-xs text-[#126b63]">#{i.id}</span><span className="flex-1 font-semibold truncate">{i.siteAddress||'Address not recorded'}</span><Badge value={i.status}/><ArrowRight size={15}/></Link>):<div className="p-6 text-[#71817e]">No recent inspections.</div>}</div></State></>}
