export function Inspections(){const {companyId}=useScope();const [search,setSearch]=useState('');const [status,setStatus]=useState('');const [page,setPage]=useState(1);const q=useListMissionControlInspections({companyId,search:search||undefined,status:status||undefined,page,limit:20});return <><Header kicker="DIAGNOSTICS / INSPECTIONS" title="Inspection ledger" description="Find an inspection and follow its evidence, analysis, and synchronization history." action={<Refresh run={()=>q.refetch()}/>}/><div className="grid sm:grid-cols-[1fr_190px] gap-3 max-w-2xl mb-5"><SearchField value={search} onChange={v=>{setSearch(v);setPage(1)}} placeholder="Search inspection or address"/><input className="field" value={status} onChange={e=>{setStatus(e.target.value);setPage(1)}} placeholder="Filter status" data-testid="input-status-filter"/></div><State loading={q.isLoading} error={q.isError} onRetry={()=>q.refetch()} empty={!q.data?.items.length} emptyText="No inspections match these filters."><div className="surface overflow-hidden">{q.data?.items.map(i=><Link href={`/inspections/${i.id}`} className="row-link" key={i.id} data-testid={`link-inspection-${i.id}`}><span className="mono text-xs text-[#126b63] w-16">#{i.id}</span><span className="flex-1 min-w-0"><span className="block font-bold truncate">{i.siteAddress||'Address not recorded'}</span><span className="block text-xs text-[#70817e] truncate">{i.companyName} · {i.technicianName||'Unassigned'} · {date(i.createdAt)}</span></span><Badge value={i.status}/><ArrowRight size={16} className="hidden sm:block"/></Link>)}</div><Pager page={page} totalPages={q.data?.totalPages||1} onPage={setPage}/></State></>}
export function InspectionDetail(){const {id}=useParams();const n=Number(id);const q=useGetMissionControlInspection(n);const i=q.data;return <><Back to="/inspections" label="All inspections"/><Header kicker={`DIAGNOSTICS / INSPECTION ${id}`} title={`Inspection #${id}`} description="A read-only diagnostic record sourced from the inspection service." action={<Refresh run={()=>q.refetch()}/>}/><State loading={q.isLoading} error={q.isError} onRetry={()=>q.refetch()}><DetailGrid fields={[[ 'Inspection ID',i?.id],['Company',i?.companyName],['Technician',i?.technicianName||'Unassigned'],['Status',<Badge value={i?.status}/>],['Site address',i?.siteAddress],['Created',date(i?.createdAt)],['Completed',date(i?.completedAt)],['Technician ID',i?.technicianId||'Not recorded'] ]}/><div className="grid lg:grid-cols-2 gap-5 mt-5"><div className="surface panel"><div className="eyebrow">EVIDENCE / MEDIA</div><h2 className="display text-2xl font-bold mt-2 mb-6">Media capture</h2><div className="grid grid-cols-2 gap-3">{[['Total',i?.mediaCounts?.total],['Photos',i?.mediaCounts?.photos],['Videos',i?.mediaCounts?.videos],['Pending analysis',i?.mediaCounts?.pendingAnalysis]].map(([a,b])=><div className="bg-[#edf3ed] p-5 rounded-xl" key={a}><div className="display text-3xl font-bold">{b??'—'}</div><div className="text-xs text-[#6c807b] mt-2">{a}</div></div>)}</div><p className="text-xs text-[#70817e] mt-5">Individual media URLs and device/session identifiers are not exposed by this diagnostic endpoint.</p></div><div className="surface overflow-hidden"><div className="p-6"><div className="eyebrow">PIPELINE / ANALYSIS</div><h2 className="display text-2xl font-bold mt-2">Media analysis</h2></div>{i?.analysisStatuses?.length?i.analysisStatuses.map(a=><div className="row-link" key={a.mediaId}><span className="mono text-xs flex-1">MEDIA #{a.mediaId}</span><Badge value={a.status}/><span className="text-xs text-[#70817e] hidden sm:block">{date(a.updatedAt)}</span>{a.error&&<p className="text-[#a8433e] text-xs">{a.error}</p>}</div>):<div className="p-6 text-[#70817e]">No analysis records yet.</div>}</div></div><div className="surface overflow-hidden mt-5"><div className="p-6"><div className="eyebrow">TRANSPORT / SYNCHRONIZATION</div><h2 className="display text-2xl font-bold mt-2">Sync timeline</h2></div>{i?.syncLogs?.length?i.syncLogs.map(log=><div className="row-link" key={log.id}><Clock3 size={17} className="text-[#126b63]"/><span className="flex-1"><span className="font-semibold block">{log.message}</span><span className="text-xs text-[#70817e]">{date(log.createdAt)}</span></span><Badge value={log.status}/></div>):<div className="p-6 text-[#70817e]">No sync logs recorded for this inspection.</div>}</div></State></>}
export function Incidents(){const {companyId}=useScope();const [status,setStatus]=useState('');const [severity,setSeverity]=useState('');const [page,setPage]=useState(1);const q=useListMissionControlIncidents({companyId,status:status||undefined,severity:severity||undefined,page,limit:20});return <><Header kicker="OPERATIONS / RESPONSE" title="Incident desk" description="Triage signals, establish ownership, and escalate issues without losing the thread." action={<Refresh run={()=>q.refetch()}/>}/><div className="flex gap-3 mb-5 flex-wrap"><select className="field !w-[175px]" value={status} onChange={e=>{setStatus(e.target.value);setPage(1)}} data-testid="select-incident-status"><option value="">All statuses</option>{['open','acknowledged','investigating','resolved','dismissed'].map(s=><option key={s}>{s}</option>)}</select><select className="field !w-[175px]" value={severity} onChange={e=>{setSeverity(e.target.value);setPage(1)}} data-testid="select-incident-severity"><option value="">All severities</option>{['low','medium','high','critical'].map(s=><option key={s}>{s}</option>)}</select></div><State loading={q.isLoading} error={q.isError} onRetry={()=>q.refetch()} empty={!q.data?.items.length} emptyText="No incidents in this scope."><div className="surface overflow-hidden">{q.data?.items.map(i=><Link href={`/incidents/${i.id}`} className="row-link" key={i.id} data-testid={`link-incident-${i.id}`}><span className={`w-1 h-11 rounded ${tone(i.severity)==='bad'?'bg-[#b24d44]':'bg-[#e3b66d]'}`}/><span className="flex-1 min-w-0"><span className="font-bold block truncate">{i.title}</span><span className="text-xs text-[#70817e] truncate block">{i.companyName} · {date(i.createdAt)} · {i.assignedTo||'Unassigned'}</span></span><Badge value={i.severity}/><Badge value={i.status}/><ArrowRight size={15} className="hidden sm:block"/></Link>)}</div><Pager page={page} totalPages={q.data?.totalPages||1} onPage={setPage}/></State></>}
function safeSourcePart(value?:string){
  if(!value)return 'Not recorded';
  // References are plain text, never navigable URLs or credentials.
  return /^[a-zA-Z0-9_-]{1,64}$/.test(value) ? value : '[reference redacted]';
}
function IncidentReferences({incident}:{incident?:{
  companyId:number;companyName:string;inspectionId?:number;userId?:string;
  sessionId?:number;sourceType?:string;sourceId?:string;
}}){
  const userId=incident?.userId||'';
  const technician=useGetMissionControlTechnician(userId,{
    query:{queryKey:getGetMissionControlTechnicianQueryKey(userId),enabled:!!userId,retry:false}
  });
  if(!incident)return null;
  return <section className="surface mt-5 overflow-hidden" aria-label="Related records">
    <div className="p-6 border-b border-[#e5e9e3]"><div className="eyebrow">TRACE / RELATED RECORDS</div><h2 className="display text-2xl font-bold mt-2">Follow the signal</h2></div>
    <div className="grid sm:grid-cols-2 lg:grid-cols-4">
      <div className="p-5 border-r border-b border-[#e5e9e3]"><div className="label">Company</div><Link href={`/companies/${incident.companyId}`} className="font-bold text-[#126b63] inline-flex items-center gap-1 hover:underline" data-testid="link-incident-company">{incident.companyName} <ArrowRight size={14}/></Link></div>
      {incident.inspectionId!=null&&<div className="p-5 border-r border-b border-[#e5e9e3]"><div className="label">Inspection</div><Link href={`/inspections/${incident.inspectionId}`} className="font-bold text-[#126b63] inline-flex items-center gap-1 hover:underline" data-testid="link-incident-inspection">#{incident.inspectionId} <ArrowRight size={14}/></Link></div>}
      {incident.userId&&<div className="p-5 border-r border-b border-[#e5e9e3]"><div className="label">User ID</div>{technician.data?<Link href={`/technicians/${encodeURIComponent(incident.userId)}`} className="font-bold text-[#126b63] inline-flex items-center gap-1 hover:underline break-all" data-testid="link-incident-technician">{technician.data.name} · {incident.userId} <ArrowRight size={14}/></Link>:<span className="font-semibold break-all" data-testid="text-incident-user-id">{incident.userId}</span>}</div>}
      {incident.sessionId!=null&&<div className="p-5 border-r border-b border-[#e5e9e3]"><div className="label">Device session</div><Link href={`/device-sessions/${incident.sessionId}`} className="font-bold text-[#126b63] inline-flex items-center gap-1 hover:underline" data-testid="link-incident-session">#{incident.sessionId} <ArrowRight size={14}/></Link></div>}
    </div>
    {(incident.sourceType||incident.sourceId)&&<div className="p-5 bg-[#edf3ed]"><div className="label">Source reference</div><div className="mono text-xs break-all" data-testid="text-incident-source">{safeSourcePart(incident.sourceType)} / {safeSourcePart(incident.sourceId)}</div></div>}
  </section>;
}
export function IncidentDetail(){
  const {id}=useParams();const n=Number(id);
  const q=useGetMissionControlIncident(n);const m=useUpdateMissionControlIncident();const qc=useQueryClient();
  const [assignee,setAssignee]=useState('');const [note,setNote]=useState('');const [severity,setSeverity]=useState('high');const [error,setError]=useState('');
  const i=q.data;
  const submit=(data:{action:'acknowledge'|'assign'|'escalate';assigneeId?:string;severity?:'low'|'medium'|'high'|'critical';note?:string})=>m.mutate({id:n,data},{onSuccess:()=>{setNote('');setError('');qc.invalidateQueries({queryKey:getGetMissionControlIncidentQueryKey(n)});qc.invalidateQueries({queryKey:['/api/mission-control/incidents']});qc.invalidateQueries({queryKey:['/api/mission-control/audit']})},onError:e=>setError(String(e))});
  return <><Back to="/incidents" label="Incident desk"/><Header kicker={`RESPONSE / INCIDENT ${id}`} title={i?.title||`Incident #${id}`} description={i?.description} action={<Refresh run={()=>q.refetch()}/>}/>
    <State loading={q.isLoading} error={q.isError} onRetry={()=>q.refetch()}>
      <DetailGrid fields={[[ 'Severity',<Badge value={i?.severity}/>],['Status',<Badge value={i?.status}/>],['Company',i?.companyName],['Owner',i?.assignedTo||'Unassigned'],['Opened',date(i?.createdAt)],['Acknowledged',date(i?.acknowledgedAt)]]}/>
      <IncidentReferences incident={i}/>
      <div className="grid lg:grid-cols-2 gap-5 mt-5">
        <div className="surface panel"><div className="eyebrow">RESPONSE ACTIONS</div><h2 className="display text-2xl font-bold mt-2">Take ownership</h2><p className="text-[#70817e] my-4">Acknowledge the incident to make the response visible.</p><button className="btn btn-primary" disabled={m.isPending||i?.status!=='open'} onClick={()=>submit({action:'acknowledge',note:note||undefined})} data-testid="button-acknowledge">Acknowledge incident <Check size={16}/></button><div className="divider my-6"/><label className="label" htmlFor="assignee">Assignee user ID</label><input id="assignee" className="field" value={assignee} onChange={e=>setAssignee(e.target.value)} placeholder="Enter a valid user ID" data-testid="input-assignee"/><button className="btn btn-dark mt-3" disabled={!assignee.trim()||m.isPending} onClick={()=>submit({action:'assign',assigneeId:assignee.trim(),note:note||undefined})} data-testid="button-assign">Assign owner</button></div>
        <div className="surface panel"><div className="eyebrow">ESCALATION</div><h2 className="display text-2xl font-bold mt-2">Raise priority</h2><p className="text-[#70817e] my-4">Record why the severity needs to change.</p><label className="label" htmlFor="escalation-severity">Severity</label><select id="escalation-severity" className="field" value={severity} onChange={e=>setSeverity(e.target.value)} data-testid="select-escalation-severity">{['low','medium','high','critical'].map(s=><option key={s}>{s}</option>)}</select><label className="label mt-4" htmlFor="incident-note">Response note</label><textarea id="incident-note" className="field min-h-24" value={note} onChange={e=>setNote(e.target.value)} placeholder="Context for the response" data-testid="input-incident-note"/><button className="btn btn-danger mt-3" disabled={m.isPending||!note.trim()} onClick={()=>submit({action:'escalate',severity:severity as 'low'|'medium'|'high'|'critical',note:note.trim()})} data-testid="button-escalate">Escalate incident</button>{error&&<p className="text-[#a8433e] mt-3" role="alert">{error}</p>}</div>
      </div>
    </State>
  </>;
}
export function Audit(){const [page,setPage]=useState(1);const [action,setAction]=useState('');const [actor,setActor]=useState('');const q=useListMissionControlAudit({page,limit:25,action:action||undefined,actorId:actor||undefined});return <><Header kicker="GOVERNANCE / RECORD" title="Audit trail" description="A chronological record of actions taken in the operational environment." action={<Refresh run={()=>q.refetch()}/>}/><div className="grid sm:grid-cols-2 gap-3 max-w-xl mb-5"><input className="field" value={action} onChange={e=>{setAction(e.target.value);setPage(1)}} placeholder="Filter by action" data-testid="input-audit-action"/><input className="field" value={actor} onChange={e=>{setActor(e.target.value);setPage(1)}} placeholder="Filter by actor ID" data-testid="input-audit-actor"/></div><State loading={q.isLoading} error={q.isError} onRetry={()=>q.refetch()} empty={!q.data?.items.length} emptyText="No audit events match these filters."><div className="surface overflow-hidden">{q.data?.items.map(e=><div className="row-link items-start" key={e.id} data-testid={`row-audit-${e.id}`}><span className="w-9 h-9 rounded-lg bg-[#e5efe9] grid place-items-center text-[#126b63]"><FileClock size={17}/></span><div className="flex-1 min-w-0"><div className="font-bold">{e.action}</div><div className="text-xs text-[#6f807e] mt-1">By {e.actorName||e.actorId} · {e.targetType} #{e.targetId}</div>{e.details&&<p className="text-xs text-[#6f807e] mt-2 break-words">{e.details}</p>}</div><time className="mono text-[10px] text-[#81918f] whitespace-nowrap hidden sm:block">{date(e.createdAt)}</time></div>)}</div><Pager page={page} totalPages={q.data?.totalPages||1} onPage={setPage}/></State></>}
function TaskDetail({id,onClose}:{id:number,onClose:()=>void}){
  const q=useGetMissionControlAgentTask(id,{query:{queryKey:getGetMissionControlAgentTaskQueryKey(id),refetchInterval:5000}});
  return <div className="fixed inset-0 z-50 bg-[#142b30]/60 grid place-items-center p-4" onClick={onClose}>
    <div className="surface w-full max-w-2xl p-7 max-h-[85dvh] overflow-auto" onClick={e=>e.stopPropagation()} role="dialog" aria-modal="true" aria-label="Task detail">
      <div className="flex justify-between"><span className="eyebrow">QUINN / TASK #{id}</span><button onClick={onClose} aria-label="Close task" data-testid="button-close-task"><X size={19}/></button></div>
      <State loading={q.isLoading} error={q.isError} onRetry={()=>q.refetch()}>
        <h2 className="display text-2xl font-bold mt-5">{q.data?.companyName}</h2><Badge value={q.data?.status}/>
        <div className="mt-6"><div className="label">Request</div><p className="whitespace-pre-wrap">{q.data?.prompt}</p></div>
        <div className="mt-6"><div className="label">Quinn's advisory synthesis</div><p className="whitespace-pre-wrap text-[#506b68]">{q.data?.result||'No result recorded.'}</p></div>
        {q.data?.error&&<p className="text-[#a8433e] mt-4" role="alert">{q.data.error}</p>}
        <div className="mt-7"><div className="eyebrow">DELEGATED INVESTIGATIONS</div>
          {q.data?.delegations?.length ? q.data.delegations.map(d=><div className="border border-[#e2e8e0] rounded-lg p-4 mt-3" key={d.id}>
            <div className="flex justify-between gap-2"><strong className="capitalize">{d.specialist}</strong><Badge value={d.status}/></div>
            <p className="text-xs text-[#71817e] mt-2">Permission: {d.scope}</p>
            {d.result&&<p className="whitespace-pre-wrap text-sm mt-3">{d.result}</p>}
            {d.error&&<p className="text-[#a8433e] text-sm mt-3">{d.error}</p>}
          </div>):<p className="text-sm text-[#71817e] mt-3">No specialist work recorded yet.</p>}
        </div>
        <div className="mt-7"><div className="eyebrow">WORK TRACE</div>
          {q.data?.traces?.length ? <ol className="mt-3 border-l-2 border-[#b7d3c9] pl-4 space-y-3">{q.data.traces.map(t=><li key={t.id} className="text-sm"><span className="font-bold capitalize">{t.actor} · {t.event}</span><span className="text-[#71817e] ml-2">{date(t.createdAt)}</span><div className="text-[#506b68]">{t.detail}</div></li>)}</ol>:<p className="text-sm text-[#71817e] mt-3">No work recorded yet.</p>}
        </div>
        <p className="text-xs text-[#71817e] mt-6">Findings are read-only advice. Agent Zero cannot execute consequential actions without human approval.</p>
        <div className="mono text-[10px] text-[#778987] mt-6">CREATED {date(q.data?.createdAt)} · STARTED {date(q.data?.startedAt)} · COMPLETED {date(q.data?.completedAt)}</div>
      </State>
    </div>
  </div>;
}
export function Agents(){
  const {companyId}=useScope();
  const roster=useListMissionControlAgents({query:{refetchInterval:10000}});
  const [page,setPage]=useState(1);
  const [status,setStatus]=useState('');
  const tasks=useListMissionControlAgentTasks({companyId,status:status||undefined,page,limit:20},{query:{refetchInterval:10000}});
  const m=useCreateMissionControlAgentTask();
  const qc=useQueryClient();
  const [target,setTarget]=useState('');
  const [prompt,setPrompt]=useState('');
  const [selected,setSelected]=useState<number|null>(null);
  const companies=useListMissionControlCompanies({page:1,limit:100});
  return <>
    <Header kicker="OPERATIONS / QUINN COORDINATION" title="Executive investigations" description="ReadyLoq assistants investigate within one company at a time. Their permissions are read-only; their activity appears in each task's trace." action={<Refresh run={()=>{roster.refetch();tasks.refetch()}}/>}/>
    <State loading={roster.isLoading} error={roster.isError} onRetry={()=>roster.refetch()}>
      <div className="surface p-6 mb-5">
        <div className="flex items-center justify-between gap-4"><div><div className="eyebrow">AGENT ZERO / EXECUTION</div><h2 className="display text-2xl font-bold mt-2">Human-governed actions</h2></div><Badge value={roster.data?.agentZero?.available?'Available':'Unavailable'}/></div>
        <p className="text-[#6b7f7b] mt-3">Investigations are advisory, not executable Agent Zero jobs. {roster.data?.agentZero?.realTaskCount??0} executable jobs available. Consequential actions require separate human approval.</p>
      </div>
      <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-3 mb-8">{roster.data?.agents?.map(a=><div className="surface p-5" key={a.identity}>
        <div className="w-9 h-9 rounded-lg bg-[#e4eee9] text-[#126b63] grid place-items-center display font-bold text-lg">{a.displayName.slice(0,1)}</div>
        <div className="display text-xl font-bold mt-4">{a.displayName}</div>
        <div className="text-xs text-[#71817e] mt-2">{a.role} · ReadyLoq assistant</div>
        <p className="text-xs text-[#506b68] my-3">{a.capability}</p><Badge value={a.status}/>
      </div>)}</div>
    </State>
    <div className="grid lg:grid-cols-[.8fr_1.2fr] gap-5">
      <div className="surface panel self-start"><div className="eyebrow">QUINN / NEW INVESTIGATION</div><h2 className="display text-2xl font-bold mt-2">Queue an investigation</h2><p className="text-[#6b7f7b] my-4">Quinn delegates to relevant specialists after the worker starts. Work is recorded for a single company; no action is executed.</p>
        <label className="label" htmlFor="task-company">Company</label><select id="task-company" className="field" value={target} onChange={e=>setTarget(e.target.value)} data-testid="select-task-company"><option value="">Select company</option>{companies.data?.items.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select>
        {(companies.data?.totalPages||0)>1&&<p className="text-xs mt-2 text-[#9a611e]">Only the first 100 companies are shown.</p>}
        <label className="label mt-5" htmlFor="task-prompt">Investigation request</label><textarea id="task-prompt" className="field min-h-36" value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="What should be investigated?" data-testid="input-task-prompt"/>
        <button className="btn btn-primary mt-4" disabled={!target||!prompt.trim()||m.isPending} onClick={()=>m.mutate({data:{companyId:Number(target),prompt:prompt.trim()}},{onSuccess:d=>{setPrompt('');setSelected(d.id);qc.invalidateQueries({queryKey:['/api/mission-control/agent-tasks']});qc.invalidateQueries({queryKey:['/api/mission-control/agents']})}})} data-testid="button-create-task">{m.isPending?'Creating…':'Create task'} <ArrowRight size={15}/></button>
        {m.isError&&<p className="text-[#a8433e] mt-3" role="alert">{String(m.error)}</p>}
      </div>
      <div className="surface overflow-hidden"><div className="p-6 flex items-center justify-between"><div><div className="eyebrow">PERSISTED WORK</div><h2 className="display text-2xl font-bold mt-2">Quinn's task queue</h2></div><select className="field !w-[140px]" value={status} onChange={e=>{setStatus(e.target.value);setPage(1)}} data-testid="select-task-status"><option value="">All statuses</option>{['queued','running','completed','failed','cancelled'].map(s=><option key={s}>{s}</option>)}</select></div>
        <State loading={tasks.isLoading} error={tasks.isError} onRetry={()=>tasks.refetch()} empty={!tasks.data?.items.length} emptyText="No real tasks in this scope.">{tasks.data?.items.map(t=><button className="row-link w-full text-left" key={t.id} onClick={()=>setSelected(t.id)} data-testid={`button-task-${t.id}`}><span className="mono text-xs text-[#126b63]">#{t.id}</span><span className="flex-1 min-w-0"><span className="font-semibold block truncate">{t.prompt}</span><span className="text-xs text-[#71817e]">{t.companyName} · {date(t.createdAt)}</span></span><Badge value={t.status}/><ExternalLink size={15}/></button>)}<div className="px-5 pb-5"><Pager page={page} totalPages={tasks.data?.totalPages||1} onPage={setPage}/></div></State>
      </div>
    </div>
    {selected&&<TaskDetail id={selected} onClose={()=>setSelected(null)}/>}
  </>;
}
export function Approvals(){const [status,setStatus]=useState('pending');const [page,setPage]=useState(1);const q=useListMissionControlApprovals({status:status||undefined,page,limit:20});const m=useDecideMissionControlApproval();const qc=useQueryClient();const [selected,setSelected]=useState<{id:number;decision:'approve'|'reject'}|null>(null);const [note,setNote]=useState('');return <><Header kicker="GOVERNANCE / DECISIONS" title="Approvals" description="Review requests before allowing consequential platform changes. Decisions require a note." action={<Refresh run={()=>q.refetch()}/>}/><div className="flex gap-2 mb-5">{['pending','approved','rejected',''].map(s=><button className={`btn ${status===s?'btn-dark':'btn-light'}`} onClick={()=>{setStatus(s);setPage(1)}} key={s} data-testid={`button-approval-filter-${s||'all'}`}>{s||'All'}</button>)}</div><State loading={q.isLoading} error={q.isError} onRetry={()=>q.refetch()} empty={!q.data?.items.length} emptyText="No requests in this queue."><div className="grid lg:grid-cols-2 gap-4">{q.data?.items.map(a=><div className="surface panel" key={a.id} data-testid={`card-approval-${a.id}`}><div className="flex justify-between gap-3"><span className="eyebrow">{a.type} / #{a.id}</span><Badge value={a.status}/></div><h2 className="display text-xl font-bold mt-5 break-words">{a.request}</h2><div className="text-xs text-[#778987] mt-4">Requested by {a.requestedBy} · {date(a.createdAt)}</div>{a.note&&<p className="bg-[#eff2eb] rounded-lg p-3 text-sm mt-4">Decision note: {a.note}</p>}{a.status==='pending'&&<div className="flex gap-2 mt-5"><button className="btn btn-primary" onClick={()=>{setSelected({id:a.id,decision:'approve'});setNote('')}} data-testid={`button-approve-${a.id}`}><Check size={15}/> Approve</button><button className="btn btn-light" onClick={()=>{setSelected({id:a.id,decision:'reject'});setNote('')}} data-testid={`button-reject-${a.id}`}><X size={15}/> Reject</button></div>}</div>)}</div><Pager page={page} totalPages={q.data?.totalPages||1} onPage={setPage}/></State>{selected&&<div className="fixed inset-0 bg-[#142b30]/60 z-50 grid place-items-center p-4" onClick={()=>setSelected(null)}><div className="surface w-full max-w-md p-7" onClick={e=>e.stopPropagation()} role="dialog" aria-modal="true" aria-label="Approval decision"><div className="eyebrow">DECISION / #{selected.id}</div><h2 className="display text-3xl font-bold mt-3 capitalize">{selected.decision} request?</h2><p className="text-[#6b7f7b] mt-3">This decision is recorded and may authorize a subsequent access change.</p><label className="label mt-6" htmlFor="approval-note">Decision note (required)</label><textarea id="approval-note" className="field min-h-28" value={note} onChange={e=>setNote(e.target.value)} data-testid="input-approval-note"/>{m.isError&&<p className="text-[#a8433e] mt-3" role="alert">{String(m.error)}</p>}<div className="flex gap-2 mt-5"><button className={`btn ${selected.decision==='approve'?'btn-primary':'btn-danger'}`} disabled={!note.trim()||m.isPending} onClick={()=>m.mutate({id:selected.id,data:{decision:selected.decision,note:note.trim()}},{onSuccess:()=>{setSelected(null);qc.invalidateQueries({queryKey:['/api/mission-control/approvals']});qc.invalidateQueries({queryKey:['/api/mission-control/audit']})}})} data-testid="button-confirm-decision">{m.isPending?'Saving…':`Confirm ${selected.decision}`}</button><button className="btn btn-light" onClick={()=>setSelected(null)} data-testid="button-cancel-decision">Cancel</button></div></div></div>}</>}